import { getState, recordAttempt } from './store.js';
import { modules, questions } from './data.js';
import { normalizeAnswer } from './utils.js';

const STORAGE_KEY='accounting-mastery-hub-v1';
const DIFF_MAP={easy:'easy',normal:'medium',hard:'hard',brutal:'tricky'};
const THEORY=[
  {id:'t-control',marks:4,moduleId:'3.2',q:'Explain why a business maintains control accounts.',meaning:'Explain the reasons a business uses control accounts and why those reasons help the business.',important:['The question asks for reasons, not how to prepare the accounts.','You need to develop each reason: say how it helps.'],points:['Provides an independent check on the personal ledgers.','Helps locate errors.','Provides quick total trade receivables / trade payables figures.'],answer:'Control accounts provide an independent check on the personal ledgers, helping the business find errors. They also give quick total trade receivables or trade payables figures.',source:'Pearson-style practice'},
  {id:'t-computer',marks:5,moduleId:'1.3',q:'Advise a business whether it should computerise its accounting system.',meaning:'Give benefits and drawbacks of computerising, then give a justified recommendation.',important:['The command word is advise, so a judgement is needed.','Use effects such as speed, accuracy, cost, training and security.'],points:['Transactions can be processed more quickly.','Automatic calculations may reduce arithmetic errors.','Reports can be produced quickly.','There may be setup, training and security costs/risks.'],answer:'Computerising can speed up transaction processing and automatic calculations can reduce arithmetic errors. It can also produce reports quickly. However, the business may face software, training and security costs. It should computerise if the time savings and better information are worth these costs.',source:'Pearson-style practice'},
  {id:'t-dep',marks:5,moduleId:'2.5',q:'Evaluate changing from straight-line to reducing-balance depreciation for motor vehicles.',meaning:'Compare the effect of the two methods, link the method to how the vehicles lose value, and reach a justified conclusion.',important:['Vehicles may lose more value when new.','A change affects depreciation expense, carrying value and profit between years.','Consistency does not mean a method can never change; a change may be justified if another method is more appropriate.'],points:['Reducing balance gives higher depreciation in earlier years and lower depreciation later.','This may better match vehicles that lose more value when new.','The change affects profit and carrying value between periods.','A justified change should use the more appropriate method consistently thereafter.'],answer:'Reducing balance charges more depreciation in the early years, which may better reflect vehicles losing more value when new. This changes profit and carrying value compared with straight-line. Although methods should normally be consistent, changing may be reasonable if reducing balance is now more appropriate and is then applied consistently.',source:'Pearson-style practice'}
];
const ENGLISH=[
  ['State','Write the answer only. No explanation unless needed.','State one source document.','Writing a paragraph.'],
  ['Identify','Pick or name the correct item from the information.','Identify one stakeholder.','Explaining the whole topic.'],
  ['Name','Give the correct name or term.','Name the accounting concept used.','Adding unnecessary explanation.'],
  ['Give','Provide the requested point or example.','Give one reason for preparing a bank reconciliation.','Giving several points when one is required.'],
  ['Calculate','Work out the figure. Show working when useful.','Calculate depreciation for the year.','Writing a theory explanation instead of a calculation.'],
  ['Prepare','Set out the required accounting statement/account in the correct format.','Prepare the trade receivables control account.','Only giving the final balance.'],
  ['Complete','Fill in the missing parts of the given format.','Complete the trial balance.','Redrawing everything unnecessarily.'],
  ['Explain','Give a point and say why/how it matters.','Computers process transactions faster, saving staff time.','Writing only “computers are faster”.'],
  ['Describe','Say what happens or what something is like.','Describe how a petty cash system operates.','Giving a judgement when none is asked.'],
  ['Distinguish','Show the difference between two things.','Distinguish capital expenditure from revenue expenditure.','Defining only one side.'],
  ['Compare','Show similarities and/or differences as required.','Compare straight-line and reducing-balance depreciation.','Writing about only one method.'],
  ['Assess','Consider relevant factors and form a supported view.','Assess whether a control account would help the business.','Listing points without linking them to the situation.'],
  ['Evaluate','Consider both sides/effects and reach a justified conclusion.','Evaluate a change in depreciation method.','Giving an opinion with no accounting reason.'],
  ['Advise','Recommend what should be done and justify it.','Advise whether the business should computerise.','Giving benefits only and no recommendation.']
];

let applying=false;
let practice={paper:'all',type:'all',difficulty:'normal',module:'all',index:0,answer:'',guess:false,idk:false,confidence:'medium',result:null,guideStep:0,simpler:false,revealed:false,start:Date.now()};
let theoryIndex=0,theoryAnswer='',theoryAnalysed=false,examSpace=true;
let englishOpen='Explain',englishQuizIndex=0,englishFeedback='';
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function page(){return location.hash.replace('#','')||'dashboard';}
function mod(id){return modules.find(m=>m.id===id);}
function saveDirect(mutator){const s=getState();mutator(s);localStorage.setItem(STORAGE_KEY,JSON.stringify(s));}
function quickRule(q){const e=(q?.explanation||'').trim();if(!e)return 'Read the command word, use the accounting rule, then apply it to the figures or scenario.';return e.split(/[.!?]/)[0]+'.';}
function practicePool(){const mapped=DIFF_MAP[practice.difficulty];return questions.filter(q=>(practice.paper==='all'||q.paper===practice.paper)&&(practice.type==='all'||q.type===practice.type)&&(practice.module==='all'||q.moduleId===practice.module)&&(practice.difficulty==='normal'||q.difficulty===mapped));}
function currentQ(){const pool=practicePool();return pool[practice.index%Math.max(pool.length,1)];}
function resetAttempt(next=false){if(next)practice.index++;practice.answer='';practice.guess=false;practice.idk=false;practice.confidence='medium';practice.result=null;practice.guideStep=0;practice.simpler=false;practice.revealed=false;practice.start=Date.now();}
function isCorrect(q,answer){const a=normalizeAnswer(answer),e=normalizeAnswer(q.answer);if(q.options)return a===e;const na=a.match(/-?\d+(?:\.\d+)?/g)?.join('|'),ne=e.match(/-?\d+(?:\.\d+)?/g)?.join('|');return !!((na&&ne&&na===ne)||a===e||(a.length>12&&e.includes(a)));}
function sidebarNav(){const nav=document.querySelector('.v3-nav-primary');if(!nav)return;let theory=nav.querySelector('[data-v3-nav-link="theory"]');if(theory){const b=theory.querySelector('b');if(b)b.textContent='Theory Trainer';}if(!nav.querySelector('[data-v4-english]')){const a=document.createElement('a');a.href='#english';a.className='v3-nav-item';a.dataset.v4English='1';a.innerHTML='<span>Aa</span><b>Exam English</b>';nav.appendChild(a);}}
function filtersMarkup(){return `<section class="p2-filters"><label>Paper<select id="p2-paper"><option value="all">All</option><option value="P1">Paper 1</option><option value="P2">Paper 2</option></select></label><label>Type<select id="p2-type"><option value="all">All</option><option value="mcq">MCQ</option><option value="short">Short</option><option value="calculation">Calculation</option><option value="theory">Theory</option><option value="ledger">Ledger</option></select></label><label>Difficulty<select id="p2-diff"><option value="easy">Easy</option><option value="normal">Normal</option><option value="hard">Hard</option><option value="brutal">Brutal</option></select></label><label>Module<select id="p2-module"><option value="all">All modules</option>${modules.map(m=>`<option value="${m.id}">${m.code} ${esc(m.name)}</option>`).join('')}</select></label></section>`;}
function guideMarkup(q){const m=mod(q.moduleId);const info=q.question.length>170?q.question.slice(0,170)+'…':q.question;const steps=[['1','What is the question asking?',q.type==='calculation'?'Work out the required accounting figure using the correct method.':q.type==='mcq'?'Choose the option that matches the accounting rule.':'Give the accounting point the command word asks for, then apply/explain it.'],['2','What information matters?',`Focus on: ${esc(info)}`],['3','What accounting topic is this testing?',`${esc(m?.code||'')} ${esc(m?.name||'Accounting')}`],['4','How should I think about it?',practice.simpler?`Very simple: first name the rule for ${esc(m?.name||'this topic')}. Then ask: what does that rule make me do in this exact question?`:'Do not jump to an answer. Identify the rule, connect it to the wording or figures, then eliminate anything that does not fit.'],['5','Try again','Now answer once more without looking at the final answer.'],['6','Worked answer',practice.revealed?`<b>${esc(q.answer)}</b><br><span>${esc(q.explanation)}</span>`:'The answer is still hidden. Reveal it only after you have tried again.']];return `<section class="p2-guide"><div class="p2-guide-title"><div><span>GUIDED HELP</span><h3>I don’t understand this question</h3></div><button data-p2-close-help>×</button></div>${steps.slice(0,Math.min(practice.guideStep,6)).map(s=>`<article><b>STEP ${s[0]}</b><h4>${s[1]}</h4><p>${s[2]}</p></article>`).join('')}<div class="p2-guide-actions">${practice.guideStep<5?'<button class="btn btn-primary" data-p2-guide-next>Next step</button>':''}<button class="btn btn-secondary" data-p2-simpler>Explain even simpler</button>${practice.guideStep>=5&&!practice.revealed?'<button class="btn btn-secondary" data-p2-reveal>Reveal worked answer</button>':''}</div></section>`;}
function resultMarkup(q,m){const correct=practice.result;return `<section class="p2-result ${correct?'good':'bad'}"><div class="p2-result-main"><div class="p2-result-icon">${correct?'✓':'×'}</div><div><span>${correct?'CORRECT':'NEEDS REVIEW'}</span><h3>${correct?q.marks:0}/${q.marks} marks • Confidence: ${esc(practice.confidence)}</h3><p>${practice.guess?'Correct/attempted while guessing — treat this as low confidence.':''}${practice.idk?' You selected “I don’t know”, so this topic needs revision.':''}</p></div></div><div class="p2-result-grid"><div><b>Answer</b><p>${esc(q.answer)}</p></div><div><b>Why</b><p>${esc(q.explanation)}</p></div><div><b>Remember this</b><p>${esc(quickRule(q))}</p></div><div><b>Topic</b><p>${esc(m?.code||'')} ${esc(m?.name||'')}</p></div></div></section>`;}
function practiceMarkup(){const pool=practicePool(),q=currentQ();if(!q)return `<div class="p2-page"><div class="p2-head"><span>Practice</span><h1>No questions match</h1><p>Choose broader filters.</p></div>${filtersMarkup()}</div>`;const m=mod(q.moduleId),letters=['A','B','C','D'];return `<div class="p2-page"><div class="p2-head"><div><span>SMART PRACTICE</span><h1>Practice Questions</h1><p>Answer, record confidence, and get help without revealing the answer too early.</p></div><div class="p2-badge">${pool.length} matching</div></div>${filtersMarkup()}<section class="p2-question-card"><div class="p2-qmeta"><span>${q.paper}</span><span>${esc(q.type.toUpperCase())}</span><span>${esc(practice.difficulty.toUpperCase())}</span><span>${q.marks} mark${q.marks===1?'':'s'}</span><span>${esc(m?.code||'')} ${esc(m?.name||'')}</span></div><h2>${esc(q.question)}</h2>${q.options?`<div class="p2-options">${q.options.map((o,i)=>`<button class="p2-option ${practice.answer===o?'selected':''}" data-p2-option="${esc(o)}" ${practice.result!==null?'disabled':''}><b>${letters[i]||i+1}</b><span>${esc(o)}</span></button>`).join('')}</div>`:`<textarea id="p2-answer" class="${examSpace?'exam-space marks-'+Math.min(6,q.marks):''}" ${practice.result!==null?'disabled':''} placeholder="Write your exam answer here...">${esc(practice.answer)}</textarea>`}${practice.result===null?`<div class="p2-confidence"><span>How sure are you?</span>${['low','medium','high'].map(x=>`<button data-p2-confidence="${x}" class="${practice.confidence===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="p2-answer-flags"><button data-p2-flag="guess" class="${practice.guess?'on':''}">I’m guessing</button><button data-p2-flag="idk" class="${practice.idk?'on':''}">I don’t know</button></div>`:''}<div class="p2-actions">${practice.result===null?`<button class="btn btn-primary" data-p2-submit ${practice.answer.trim()||practice.idk?'':'disabled'}>Check answer</button><button class="btn btn-help" data-p2-help>I don’t understand this question</button>`:`<button class="btn btn-primary" data-p2-next>Next question</button>`}<button class="btn btn-secondary" data-p2-space>${examSpace?'Exam Space Mode':'Normal Writing Mode'}</button></div>${practice.guideStep?guideMarkup(q):''}${practice.result!==null?resultMarkup(q,m):''}</section></div>`;}
function submitPractice(){const q=currentQ();if(!q)return;if(practice.idk&&!practice.answer)practice.answer='I do not know';const ok=isCorrect(q,practice.answer);practice.result=ok;recordAttempt(q.id,practice.answer,ok,practice.idk?'rule':'unclassified',{confidence:practice.guess?'low':practice.confidence,guessed:practice.guess,didNotKnow:practice.idk,difficultyMode:practice.difficulty,timeSeconds:Math.round((Date.now()-practice.start)/1000),assessmentObjectives:q.assessmentObjectives});renderCustom();}
function theoryMarkup(){const t=THEORY[theoryIndex%THEORY.length],m=mod(t.moduleId),words=theoryAnswer.trim()?theoryAnswer.trim().split(/\s+/).length:0,pointHits=t.points.filter(p=>theoryAnswer.toLowerCase().split(/\W+/).some(w=>w.length>5&&p.toLowerCase().includes(w))).length,hasDev=/because|therefore|so |which|this means|as a result|causes|reduces|increases|helps|allows/i.test(theoryAnswer),hasJudgement=/therefore|overall|recommend|advise|should|reasonable|appropriate/i.test(theoryAnswer);return `<div class="p2-page"><div class="p2-head"><div><span>ADVANCED THEORY TRAINER</span><h1>Build the answer yourself</h1><p>Question → meaning → scenario → points → your answer → analysis → simplest improved answer.</p></div><div class="p2-badge">Suggested exam structure</div></div><section class="p2-theory-q"><div><span>${t.source}</span><h2>${esc(t.q)}</h2></div><strong>${t.marks}<small>marks</small></strong></section><div class="p2-theory-steps"><section><b>1</b><div><h3>What does the question mean?</h3><p>${esc(t.meaning)}</p></div></section><section><b>2</b><div><h3>Important information</h3><ul>${t.important.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></section><section><b>3</b><div><h3>Accounting points I could use</h3><ul>${t.points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></section></div><section class="p2-write"><div class="p2-write-top"><div><span>YOUR ANSWER</span><h3>${examSpace?'Exam Answer Space':'Normal Writing Mode'}</h3></div><button class="p2-toggle" data-p2-space>${examSpace?'Exam Space Mode ON':'Normal Writing Mode'}</button></div><textarea id="p2-theory-answer" class="${examSpace?'exam-space marks-'+t.marks:''}" placeholder="Write it as you would in the exam...">${esc(theoryAnswer)}</textarea><div class="p2-wordrow"><span>${words} words</span><span>${examSpace?'Keep it concise: use the space, not a memorised essay.':'Write freely, then shorten it.'}</span></div><div class="p2-actions"><button class="btn btn-primary" data-p2-analyse>Mark / analyse answer</button><button class="btn btn-help" data-p2-theory-help>I don’t understand this question</button><button class="btn btn-secondary" data-p2-next-theory>Next question</button></div></section>${document.documentElement.dataset.p2TheoryHelp==='1'?`<section class="p2-guide"><div class="p2-guide-title"><div><span>GUIDED HELP</span><h3>Understand before writing</h3></div><button data-p2-theory-close>×</button></div><article><b>STEP 1</b><h4>What is it asking?</h4><p>${esc(t.meaning)}</p></article><article><b>STEP 2</b><h4>What matters?</h4><p>${esc(t.important[0])}</p></article><article><b>STEP 3</b><h4>What topic?</h4><p>${esc(m?.code||'')} ${esc(m?.name||'')}</p></article><article><b>STEP 4</b><h4>How should I think?</h4><p>Choose one accounting point, explain its effect, apply it to the situation, then add a balanced point and judgement if the command word needs one.</p></article><button class="btn btn-secondary" data-p2-theory-close>Try again</button></section>`:''}${theoryAnalysed?`<section class="p2-analysis"><h2>Answer analysis</h2><p class="p2-disclaimer">This is a suggested exam structure check, not an official Pearson mark allocation.</p><div class="p2-compare"><div class="credit"><b>What looks creditworthy</b><p>${pointHits?`${pointHits} relevant accounting idea(s) appear to be present.`:'No clear relevant point was detected yet.'}</p><p>${hasDev?'You developed at least one idea.':'Add why/how the point matters.'}</p></div><div class="missing"><b>What may be missing</b><p>${t.marks>=4&&!hasJudgement?'A justified conclusion/advice may be needed for this style of question.':'Your ending has a judgement/recommendation cue.'}</p><p>${words<12?'The answer is probably too short to develop enough points.':'Check that every sentence earns its space.'}</p></div><div class="improved"><b>Simplest improved exam answer</b><p>${esc(t.answer)}</p></div></div><div class="p2-analysis-actions"><button class="btn btn-secondary" data-p2-why>Why did I lose marks?</button><button class="btn btn-primary" data-p2-show-simple>Show simplest full answer</button></div><div id="p2-extra-feedback"></div></section>`:''}</div>`;}
function englishMarkup(){const selected=ENGLISH.find(x=>x[0]===englishOpen)||ENGLISH[7],quiz=ENGLISH[englishQuizIndex%ENGLISH.length];return `<div class="p2-page"><div class="p2-head"><div><span>EXAM ENGLISH</span><h1>Understand exactly what the question wants</h1><p>Command words translated into very simple English, with tiny Accounting examples.</p></div><div class="p2-badge">${getState().examEnglish?.correct||0}/${getState().examEnglish?.quizAttempts||0} quiz correct</div></div><div class="p2-english-layout"><aside>${ENGLISH.map(x=>`<button data-p2-command="${x[0]}" class="${x[0]===selected[0]?'active':''}">${x[0]}</button>`).join('')}</aside><section class="p2-command-card"><span>COMMAND WORD</span><h2>${selected[0].toUpperCase()}</h2><div class="p2-command-grid"><article><b>What it means</b><p>${esc(selected[1])}</p></article><article><b>What the examiner expects</b><p>${['State','Identify','Name','Give'].includes(selected[0])?'A short direct point.':['Calculate','Prepare','Complete'].includes(selected[0])?'The correct accounting working/format and result.':'A developed answer that follows the command word.'}</p></article><article><b>How much explanation?</b><p>${['State','Identify','Name','Give'].includes(selected[0])?'Usually very little.':['Explain','Describe','Distinguish','Compare'].includes(selected[0])?'Enough to develop the required points.':'Use relevant reasons/effects and a supported judgement where required.'}</p></article><article><b>Tiny Accounting example</b><p>${esc(selected[2])}</p></article><article class="wide"><b>Common mistake</b><p>${esc(selected[3])}</p></article></div></section></div><section class="p2-quiz"><span>MINI QUIZ</span><h2>What is this command word asking you to do?</h2><div class="p2-quiz-q"><b>${quiz[0]}</b><p>${esc(quiz[2])}</p></div><div class="p2-quiz-options"><button data-p2-quiz="short">Give a direct point / required result</button><button data-p2-quiz="develop">Develop why/how it matters</button><button data-p2-quiz="judge">Consider evidence and give a supported judgement</button></div>${englishFeedback?`<div class="p2-quiz-feedback">${esc(englishFeedback)}</div>`:''}<button class="btn btn-secondary" data-p2-next-quiz>Next command word</button></section></div>`;}
function quizAnswer(word){if(['State','Identify','Name','Give','Calculate','Prepare','Complete'].includes(word))return 'short';if(['Explain','Describe','Distinguish','Compare'].includes(word))return 'develop';return 'judge';}
function recordEnglish(ok){saveDirect(s=>{s.examEnglish=s.examEnglish||{completed:[],quizAttempts:0,correct:0};s.examEnglish.quizAttempts=(s.examEnglish.quizAttempts||0)+1;if(ok)s.examEnglish.correct=(s.examEnglish.correct||0)+1;if(ok&&!s.examEnglish.completed.includes(ENGLISH[englishQuizIndex%ENGLISH.length][0]))s.examEnglish.completed.push(ENGLISH[englishQuizIndex%ENGLISH.length][0]);});}
function setSelects(){[['p2-paper',practice.paper],['p2-type',practice.type],['p2-diff',practice.difficulty],['p2-module',practice.module]].forEach(([id,val])=>{const e=document.getElementById(id);if(e)e.value=val;});}
function renderCustom(){const host=document.querySelector('.content');if(!host)return;const p=page();if(!['practice','theory','english'].includes(p))return;applying=true;try{host.innerHTML=p==='practice'?practiceMarkup():p==='theory'?theoryMarkup():englishMarkup();host.dataset.p2Page=p;setSelects();wireCustom();}finally{applying=false;}}
function wireCustom(){document.querySelectorAll('[data-p2-option]').forEach(b=>b.addEventListener('click',()=>{practice.answer=b.dataset.p2Option;renderCustom();}));const ans=document.getElementById('p2-answer');ans?.addEventListener('input',()=>practice.answer=ans.value);document.querySelectorAll('[data-p2-confidence]').forEach(b=>b.addEventListener('click',()=>{practice.confidence=b.dataset.p2Confidence;renderCustom();}));document.querySelectorAll('[data-p2-flag]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.p2Flag;practice[k]=!practice[k];if(k==='idk'&&practice.idk)practice.guess=false;renderCustom();}));document.querySelector('[data-p2-submit]')?.addEventListener('click',submitPractice);document.querySelector('[data-p2-next]')?.addEventListener('click',()=>{resetAttempt(true);renderCustom();});document.querySelectorAll('[data-p2-space]').forEach(b=>b.addEventListener('click',()=>{examSpace=!examSpace;renderCustom();}));document.querySelector('[data-p2-help]')?.addEventListener('click',()=>{practice.guideStep=Math.max(1,practice.guideStep);renderCustom();});document.querySelector('[data-p2-close-help]')?.addEventListener('click',()=>{practice.guideStep=0;renderCustom();});document.querySelector('[data-p2-guide-next]')?.addEventListener('click',()=>{practice.guideStep=Math.min(5,practice.guideStep+1);renderCustom();});document.querySelector('[data-p2-simpler]')?.addEventListener('click',()=>{practice.simpler=true;practice.guideStep=Math.max(4,practice.guideStep);renderCustom();});document.querySelector('[data-p2-reveal]')?.addEventListener('click',()=>{practice.revealed=true;practice.guideStep=6;renderCustom();});[['p2-paper','paper'],['p2-type','type'],['p2-diff','difficulty'],['p2-module','module']].forEach(([id,key])=>document.getElementById(id)?.addEventListener('change',e=>{practice[key]=e.target.value;resetAttempt();renderCustom();}));const ta=document.getElementById('p2-theory-answer');ta?.addEventListener('input',()=>theoryAnswer=ta.value);document.querySelector('[data-p2-analyse]')?.addEventListener('click',()=>{theoryAnswer=document.getElementById('p2-theory-answer')?.value||'';theoryAnalysed=true;renderCustom();});document.querySelector('[data-p2-next-theory]')?.addEventListener('click',()=>{theoryIndex=(theoryIndex+1)%THEORY.length;theoryAnswer='';theoryAnalysed=false;document.documentElement.dataset.p2TheoryHelp='0';renderCustom();});document.querySelector('[data-p2-theory-help]')?.addEventListener('click',()=>{document.documentElement.dataset.p2TheoryHelp='1';renderCustom();});document.querySelectorAll('[data-p2-theory-close]').forEach(b=>b.addEventListener('click',()=>{document.documentElement.dataset.p2TheoryHelp='0';renderCustom();}));document.querySelector('[data-p2-why]')?.addEventListener('click',()=>{const e=document.getElementById('p2-extra-feedback');if(e)e.innerHTML='<div class="p2-extra">Marks are usually lost when a point is missing, not developed, not applied, or the required judgement is absent. Check the exact Pearson mark scheme when available.</div>';});document.querySelector('[data-p2-show-simple]')?.addEventListener('click',()=>{const e=document.getElementById('p2-extra-feedback');if(e)e.innerHTML=`<div class="p2-extra"><b>Simple full response:</b><p>${esc(THEORY[theoryIndex%THEORY.length].answer)}</p></div>`;});document.querySelectorAll('[data-p2-command]').forEach(b=>b.addEventListener('click',()=>{englishOpen=b.dataset.p2Command;renderCustom();}));document.querySelectorAll('[data-p2-quiz]').forEach(b=>b.addEventListener('click',()=>{const word=ENGLISH[englishQuizIndex%ENGLISH.length][0],ok=b.dataset.p2Quiz===quizAnswer(word);englishFeedback=ok?'✓ Correct — you recognised what the command word requires.':`Not quite. ${word} means: ${ENGLISH[englishQuizIndex%ENGLISH.length][1]}`;recordEnglish(ok);renderCustom();}));document.querySelector('[data-p2-next-quiz]')?.addEventListener('click',()=>{englishQuizIndex=(englishQuizIndex+1)%ENGLISH.length;englishFeedback='';renderCustom();});}
function enhance(){if(applying)return;sidebarNav();const p=page();document.querySelectorAll('[data-v3-nav-link], [data-v4-english]').forEach(a=>a.classList.toggle('active',(a.getAttribute('href')||'')==='#'+p));if(['practice','theory','english'].includes(p)){const host=document.querySelector('.content');if(host&&host.dataset.p2Page!==p)renderCustom();}}
function schedule(){requestAnimationFrame(enhance);}
new MutationObserver(schedule).observe(document.getElementById('app'),{childList:true,subtree:true});window.addEventListener('hashchange',schedule);schedule();